#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

using namespace std;

#define int long long

int power_of_ten[1000005];
int digits[1000005];
int toggle[1000005];
int temp_digits[1000005];
long long min_score=1e18;

void evaluate()
{
    for (int i=0; i<18; i++)
    {
        digits[i]=temp_digits[i];
    }
    for (int i=0; i<17; i++)
    {
        if (toggle[i]>0)
        {
            digits[i+1]++;
            digits[i]-=10;
            digits[0]--;
        }
    }
    if (digits[0]<-6)
    {
        digits[0]+=11;
        digits[1]--;
    }
    if (digits[0]>6)
    {
        digits[0]-=11;
        digits[1]++;
    }
    long long score=0;
    for (int i=0; i<18; i++)
    {
        score+=abs(digits[i])*(i+1);
    }
    min_score=min(min_score,score);
}

void recurse(int index)
{
    if (index>=17)
    {
        evaluate();
        return;
    }
    for (int val=0; val<=1; val++)
    {
        toggle[index]=val;
        recurse(index+1);
    }
}

int main()
{
    int number;
    cin>>number;
    power_of_ten[0]=1;
    for (int i=1; i<18; i++)
    {
        power_of_ten[i]=power_of_ten[i-1]*10+1;
    }
    int temp=number;
    int pos=17;
    while (temp>0)
    {
        temp_digits[pos]=temp/power_of_ten[pos];
        temp%=power_of_ten[pos];
        pos--;
    }
    recurse(0);
    cout<<min_score;
}
